def ist_primzahl(zahl):
    if zahl < 2:
        return False
    for teiler in range(2, zahl):
        if zahl % teiler == 0:
            return False
    return True

def primzahlen_bis(n):
    ergebnis = []
    for zahl in range(2, n + 1):
        if ist_primzahl(zahl):
            ergebnis.append(zahl)
    return ergebnis

print(primzahlen_bis(20))

def collatz_schritte(zahl):
    schritte = 0
    while zahl != 1:
        if zahl % 2 == 0:
            zahl = zahl // 2
        else:
            zahl = zahl * 3 + 1
        schritte += 1
    return schritte

